WHERE S.INSERT_DATE >= #{startDtime}
  AND S.INSERT_DATE <= #{endDtime}

  AND S.PURPOSE_CD = #{purposeCd}


  AND S.SEND_STATUS = #{sendStatus}


  AND S.MBL_NO_HMAC = #{mblNoHmac}

mapper.select:
/* PlatformSmsMapper.selectSendHistoryCount */
SELECT COUNT(1)
FROM TB_SMS_AUTH_CODE S

mapper.update:
/* PlatformSmsMapper.updatePolicy */
UPDATE TB_SMS_SEND_POLICY
SET
    PHONE_WINDOW_SEC     = #{phoneWindowSec}
    , PHONE_HOUR_LIMIT   = #{phoneHourLimit}
    , PHONE_DAY_LIMIT    = #{phoneDayLimit}
    , IP_AXIS_ENABLED_YN = #{ipAxisEnabledYn}
    , IP_HOUR_LIMIT      = #{ipHourLimit}
    , IP_DAY_LIMIT       = #{ipDayLimit}
    , USER_HOUR_LIMIT    = #{userHourLimit}
    , USER_DAY_LIMIT     = #{userDayLimit}
    , GLOBAL_HOUR_LIMIT  = #{globalHourLimit}
    , UPDATE_NO          = #{operatorUserCd}
    , UPDATE_DATE        = NOW()
WHERE POLICY_ID = 'DEFAULT'
